class LibraryMember {private String id;private int limit;private int[] fines=new int[10];private int count;public LibraryMember(String i,int l){if(i==null||i.trim().length()<4)throw new IllegalArgumentException("Invalid ID");if(l<=0)throw new IllegalArgumentException("Limit must be positive");id=i;limit=l;}protected void chargeFine(int a){if(count>=10)throw new IllegalStateException("Fine history full");fines[count++]=a;}public int[] getFineHistory(){return java.util.Arrays.copyOf(fines,count);}public int getTotalFine(){int t=0;for(int i=0;i<count;i++)t+=fines[i];return t;}}
class StudentMember extends LibraryMember {private String course;public StudentMember(String i,int l,String c){super(i,l);course=c;}@Override protected void chargeFine(int amount){super.chargeFine(amount/2);}}
public class StudentDiscountFineLedgerMain {public static void main(String[] a){StudentMember s=new StudentMember("STU5",3,"CSE");s.chargeFine(100);System.out.println(s.getTotalFine());int[] h=s.getFineHistory();h[0]=999;System.out.println(java.util.Arrays.toString(s.getFineHistory()));}}
